  FT["PH-H1901"] = {"id":"PH-H1901","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2164_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Patnongon市","en":"An Act Creating Certain Barrios in the Municipality of Patnongon, Province of Antique","orig":"An Act Creating Certain Barrios in the Municipality of Patnongon, Province of Antique"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2164","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-04-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2164_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1901-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Patnongon, Province of Antique, are constituted as distinct and independent barrios, to wit:\n1. The sitios of Magranting, Tigangcal, Agsaman, Epgas, Epayo and Eglapang to be known as the barrio of Alvañiz;\n2. The sitios of Igtuba Maradiona and Igtuba Aureliana to be known as the barrio of Magsaysay;\n3. The sitios of Amarong, Tagbacan, Da-o, Yapo and Embalodan to be known as the barrio of Elio; and\n4. The sitios of Tigabobo, Tiglomabong, Maybangcal, Calagtiñgan and Bongboñgan to be known as the barrio of Vista Alegre."}},{"id":"PH-H1901-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 24, 1959."}}],"pack":"ph-p26"};
